<?php try{ $mailDb=$db??Database::conn(); $mailDb->exec("CREATE TABLE IF NOT EXISTS contact_messages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL DEFAULT '',message MEDIUMTEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_read_created (is_read,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); $mailCount=(int)$mailDb->query("SELECT COUNT(*) FROM contact_messages WHERE is_read=0 AND created_at >= NOW() - INTERVAL 24 HOUR")->fetchColumn(); $mailRows=$mailDb->query("SELECT id,name,email,subject,is_read,created_at FROM contact_messages WHERE created_at >= NOW() - INTERVAL 24 HOUR ORDER BY is_read ASC, id DESC LIMIT 6")->fetchAll(); }catch(Throwable){ $mailCount=0; $mailRows=[]; } ?>
