<style>#userDropWrap:hover #userDrop{display:block!important}#userDropWrap #userDrop{transition:opacity .15s ease}#mailDropWrap #mailDrop{transition:opacity .15s ease}</style>
<script>document.getElementById('sysUpdBtn')?.addEventListener('click',async()=>{
  const url='<?= Helper::url('admin/system-update') ?>',csrf='<?= Security::csrfToken() ?>';
  const post=async d=>{const f=new FormData();f.append('csrf',csrf);Object.entries(d).forEach(([k,v])=>f.append(k,v));const r=await fetch(url,{method:'POST',body:f});return r.json()};
  const st=await post({sub:'status'}).catch(()=>({ok:false}));
  if(!st.ok){Swal.fire('Gagal','Tidak bisa baca status sistem.','error');return}
  if(st.lock){Swal.fire('Berjalan','Update sedang berjalan. Tunggu selesai.','info');return}
  const c=await post({sub:'check'}).catch(()=>({ok:false,msg:'Koneksi gagal.'}));
  if(!c.ok){Swal.fire('Gagal',c.msg||'Cek update gagal.','error');return}
  if(c.uptodate){Swal.fire('Terbaru','Sistem sudah versi terbaru.','success');return}
  const ok=await Swal.fire({title:'Terapkan update?',html:'Ditemukan <b>'+(c.behind??'?')+' perubahan baru</b>.<br>Backup otomatis dibuat dulu.<br>Data & database hosting <b>tidak ditimpa</b>.<br><span class="text-xs text-slate-500">Versi: '+c.local.slice(0,7)+' → '+c.remote.slice(0,7)+'</span>',icon:'question',showCancelButton:true,confirmButtonText:'Ya, Update',cancelButtonText:'Batal',confirmButtonColor:'#059669'}).then(r=>r.isConfirmed);
  if(!ok)return;
  Swal.fire({title:'Memproses...',html:'Mengambil & menerapkan update.<br>Jangan tutup halaman.',allowOutsideClick:false,allowEscapeKey:false,didOpen:()=>Swal.showLoading()});
  const a=await post({sub:'apply'}).catch(()=>({ok:false,msg:'Koneksi gagal.'}));
  if(a.ok){Swal.fire('Berhasil',a.msg||'Update selesai.','success')}else{Swal.fire('Gagal',a.msg||'Update gagal.','error')}
});
document.getElementById('sideBtn')?.addEventListener('click',()=>{const s=document.getElementById('sidebar'); if(!s)return; s.classList.toggle('hidden'); s.classList.toggle('open')});(function(){const w=document.getElementById('userDropWrap'),b=document.getElementById('userBtn'),d=document.getElementById('userDrop');if(!w||!b||!d)return;let t=null;const show=()=>{clearTimeout(t);d.classList.remove('hidden')};const hide=()=>{clearTimeout(t);t=setTimeout(()=>d.classList.add('hidden'),180)};w.addEventListener('mouseenter',show);w.addEventListener('mouseleave',hide);b.addEventListener('click',e=>{e.stopPropagation();d.classList.toggle('hidden')});document.addEventListener('click',e=>{if(!w.contains(e.target))d.classList.add('hidden')});document.addEventListener('keydown',e=>{if(e.key==='Escape')d.classList.add('hidden')})})();
(function(){const w=document.getElementById('mailDropWrap'),b=document.getElementById('mailBtn'),d=document.getElementById('mailDrop');if(!w||!b||!d)return;let t=null;const show=()=>{clearTimeout(t);d.classList.remove('hidden')};const hide=()=>{clearTimeout(t);t=setTimeout(()=>d.classList.add('hidden'),220)};w.addEventListener('mouseenter',show);w.addEventListener('mouseleave',hide);b.addEventListener('click',e=>{e.stopPropagation();d.classList.toggle('hidden')});d.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;d.classList.add('hidden')});document.addEventListener('click',e=>{if(!w.contains(e.target))d.classList.add('hidden')});document.addEventListener('keydown',e=>{if(e.key==='Escape')d.classList.add('hidden')})})();</script>
